import React, { useContext } from 'react';

import { Link, useNavigate } from 'react-router-dom';

import { runInterviewInModal } from '@apps/Interview/components/InterviewRun';
import notificationHelper, { success } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';

import { AuthContext } from '../../../../contexts/AuthContext';
import { getHikingDataAsync, hikingMemberJoin } from '../../@services/hiking.service';
import { IHikingData } from '../../@types/hiking.types';

const HikingConfirm = ({ id: id_hiking }: { id: number }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [approve, setApprove] = React.useState(false);
  const [isLoading, setIsLoading] = React.useState(false);
  const navigate = useNavigate();

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    getHikingDataAsync(id_hiking).then(setHikingData);
  }, [id_hiking]);

  const handleJoin = () => {
    setIsLoading(true);
    hikingMemberJoin(id_hiking)
      .then(async (res) => {
        if (Array.isArray(res) && res.length) {
          const _iter = function (index: number, arr: any[], cb: () => void) {
            if (arr[index]) {
              runInterviewInModal(arr[index].id, arr[index].name, () => {
                _iter(index + 1, arr, cb);
              });
            } else {
              cb();
            }
          };

          _iter(0, res, () => {
            hikingMemberJoin(id_hiking)
              .then((res1) => {
                setIsLoading(false);
                if (res1 && (res1 as { success: boolean }).success) {
                  success('Вы успешно подтвердили свое участие в походе', 1);
                  navigate(`/hiking/${id_hiking}`);
                }
              })
              .catch(notificationHelper.error);
          });
        } else if ((res as { success: boolean })?.success) {
          success('Вы успешно подтвердили свое участие в походе');
          navigate(`/hiking/${id_hiking}`);
          setIsLoading(false);
        }
      })
      .catch(notificationHelper.error);
  };

  if (!hikingData) {
    return <PohLoader />;
  }

  if (hikingData.hikers.find((h) => h.idUser === authContext.user?.id)) {
    notificationHelper.success('Вы уже подтвердили свое участие в походе');
    navigate(`/hiking/${id_hiking}/`);
    return null;
  }

  return (
    <>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/confirm`, text: 'Подтверждение участия', active: true },
        ]}
      />

      <PohContainer>
        <PohRow className="mt-5">
          <PohCol
            lg={{ span: 8, offset: 2 }}
            md={{ span: 10, offset: 1 }}
            sm={{ span: 12, offset: 0 }}
          >
            <h2>{hikingData.name}</h2>
            <p>{hikingData.desc}</p>
          </PohCol>
        </PohRow>
        <PohRow>
          <PohCol
            lg={{ span: 8, offset: 2 }}
            md={{ span: 10, offset: 1 }}
            sm={{ span: 12, offset: 0 }}
          >
            <p>
              Подтверждайте свое участие в походе только если вы <b>уверены </b>
              что сможете присоединиться к походу в указанные даты (
              {hikingData.start.toLocaleDateString()} — {hikingData.finish.toLocaleDateString()})
              <br />
              Это важно, так как организаторам похода нужно знать точное количество участников для
              грамотной организации похода.
            </p>
            <p>
              После подтверждения участия можно будет отказаться от участия до начала похода, но в
              таком случае вы попадете в список <Link to="/radish">редисок</Link>. Это не слишком
              престижно для тру-походника.
            </p>
          </PohCol>
        </PohRow>
        <PohRow className="mb-5">
          <PohCol
            lg={{ span: 8, offset: 2 }}
            md={{ span: 10, offset: 1 }}
            sm={{ span: 12, offset: 0 }}
          >
            <PohCheckbox
              checked={approve}
              onChange={setApprove}
              label="Подтверждаю свое участие в походе"
              disabled={isLoading}
            />

            <PohButton
              disabled={!approve || isLoading}
              title={approve ? '' : 'Требуется подтверждение (галочку надо поставить)'}
              onClick={handleJoin}
              className="d-block w-100 mt-4"
              size={ButtonSize.Big}
              variant={ButtonVariant.Success}
            >
              Точно пойду
            </PohButton>
          </PohCol>
        </PohRow>
      </PohContainer>
    </>
  );
};

export default HikingConfirm;
